  buttons.appendChild(button('다음 화 읽기', '다음 화 읽기', { h: 36, px: 12, gap: 4, r: 10, fill: 'ember', size: 13, lh: 20, ls: 0.13, color: 'eggshell', after: chevron(16, 'eggshell', 'forward') }));
